) j), x as (select array_remove(array[case when coalesce((true), false) then null else 'fichier' end, case when coalesce(((e.j ->> 'table')::boolean), false) then null else 'table' end, case when coalesce(((e.j ->> 'rls')::boolean), false) then null else 'rls' end, case when coalesce((e.j ->> 'forme' = '948f3ab6286e46db9db58b0041275a79'), false) then null else 'forme' end, case when coalesce((json_array_length(e.j -> 'droits') = 0), false) then null else 'droits' end, case when coalesce(((e.j ->> 'droits_colonnes') is null), false) then null else 'droits_colonnes' end, case when coalesce(((e.j ->> 'regles_table') is null), false) then null else 'regles_table' end, case when coalesce(((e.j -> 'regles')::jsonb = case when exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'app_data' and policyname = 'vrm_lecture_privee') and exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'app_data' and policyname = 'abonnement_requis_effacer') then '["app_data:abonnement_requis:RESTRICTIVE:ALL:authenticated:true:(selectvrm_acces_ok())","app_data:equipe_lit:PERMISSIVE:SELECT:authenticated:((owner=(selectvrm_equipe_vendeur()))andvrm_equipe_id_permis(id)):","app_data:vrm_lecture_privee:RESTRICTIVE:SELECT:authenticated:((owner=(selectauth.uid()))or((owner=(selectvrm_equipe_vendeur()))andvrm_equipe_id_permis(id))):"]'::jsonb when exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'app_data' and policyname = 'vrm_lecture_privee') then '["app_data:abonnement_requis:RESTRICTIVE:ALL:authenticated:((selectvrm_acces_ok())or(owner=(selectvrm_equipe_vendeur()))):(selectvrm_acces_ok())","app_data:equipe_lit:PERMISSIVE:SELECT:authenticated:((owner=(selectvrm_equipe_vendeur()))andvrm_equipe_id_permis(id)):","app_data:vrm_lecture_privee:RESTRICTIVE:SELECT:authenticated:((owner=(selectauth.uid()))or((owner=(selectvrm_equipe_vendeur()))andvrm_equipe_id_permis(id))):"]'::jsonb when exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'app_data' and policyname = 'abonnement_requis_effacer') then '["app_data:abonnement_requis:RESTRICTIVE:ALL:authenticated:true:(selectvrm_acces_ok())","app_data:equipe_lit:PERMISSIVE:SELECT:authenticated:((owner=(selectvrm_equipe_vendeur()))andvrm_equipe_id_permis(id)):"]'::jsonb else '["app_data:abonnement_requis:RESTRICTIVE:ALL:authenticated:((selectvrm_acces_ok())or(owner=(selectvrm_equipe_vendeur()))):(selectvrm_acces_ok())","app_data:equipe_lit:PERMISSIVE:SELECT:authenticated:((owner=(selectvrm_equipe_vendeur()))andvrm_equipe_id_permis(id)):"]'::jsonb end), false) then null else 'regles' end, case when coalesce(((e.j ->> 'restrictives_bloquantes') is null), false) then null else 'restrictives_bloquantes' end, case when coalesce(((e.j -> 'fonctions')::jsonb = '{"vrm_equipe_id_permis":{"n":1,"def":false,"cfg":["search_path=\"\""],"vol":"i","md5":"965ba87cdc7c551ba022483c54ba7aa6","auth":true,"sr":false,"anon":false},"vrm_equipe_actif":{"n":1,"def":true,"cfg":["search_path=\"\""],"vol":"s","md5":"580d623292fd1d26f68b5d28db32a2f7","auth":false,"sr":false,"anon":false},"vrm_equipe_vendeur":{"n":1,"def":true,"cfg":["search_path=\"\""],"vol":"s","md5":"fff474652a14b03a11e1bcdc98690a71","auth":true,"sr":false,"anon":false},"vrm_equipe_inviter":{"n":1,"def":true,"cfg":["search_path=\"\""],"vol":"v","md5":"03804b7843a5f934d30b504786d8557a","auth":true,"sr":false,"anon":false},"vrm_equipe_accepter":{"n":1,"def":true,"cfg":["search_path=\"\""],"vol":"v","md5":"afde096471ddc82cf33f4869fe4ab864","auth":true,"sr":false,"anon":false},"vrm_equipe_revoquer":{"n":1,"def":true,"cfg":["search_path=\"\""],"vol":"v","md5":"54ba1fc79fe91795f13fc74edbeb3e99","auth":true,"sr":false,"anon":false},"vrm_equipe_lister":{"n":1,"def":true,"cfg":["search_path=\"\""],"vol":"s","md5":"a485e525b1a718b08fdc856243b5ffed","auth":true,"sr":false,"anon":false},"vrm_equipe_colis":{"n":1,"def":true,"cfg":["search_path=\"\""],"vol":"s","md5":"e65f1ab62a68976c28cbfa2